fr.exercice_solution:
import kotlinx.coroutines.*

suspend fun loadTasksFromNetwork(): List<String> = withContext(Dispatchers.Default) {
    delay(2000L) // Simule un chargement de 2 secondes
    return@withContext listOf('Tâche 1', 'Tâche 2', 'Tâche 3')
}

fun main() = runBlocking {
    launch {
        val tasks = loadTasksFromNetwork()
        println('Données chargées: $tasks')
    }

    println('Programme en cours...')
    delay(3000L)
    println('Fin du programme')
}

