import kotlinx.coroutines.*

suspend fun loadTasksFromNetwork(): List<String> = withContext(Dispatchers.Default) {
    delay(2000L) // Simulate 2-second loading
    return@withContext listOf('Task 1', 'Task 2', 'Task 3')
}

fun main() = runBlocking {
    launch {
        val tasks = loadTasksFromNetwork()
        println('Data loaded: $tasks')
    }

    println('Program running...')
    delay(3000L)
    println('End of program')
}
